/* Landing page + solitaire offline cache (generated by /workspace/hosting/build-sw.py). */
const CACHE = 'bizy-site-c0210e04796c';
const SHELL = ['./', './index.html', './solitaire/', './solitaire/index.html', './icons/icon-180.png', './icons/icon-192.png', './favicon.ico', './apple-touch-icon.png'];
self.addEventListener('install', e => e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL.map(u => new Request(u, { cache: 'reload' })))).then(() => self.skipWaiting())));
self.addEventListener('activate', e => e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k.startsWith('bizy-site-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim())));
self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin || url.pathname.startsWith(new URL('./mahjong4/', self.registration.scope).pathname)) return;   // mahjong4 has its own worker
  e.respondWith(caches.open(CACHE).then(c => c.match(req, { ignoreSearch: true }).then(hit => {
    const net = fetch(req).then(res => { if (res.ok && res.type === 'basic' && hit) c.put(req, res.clone()); return res; });
    return hit || net;          // cache-first; refreshed in the background when online
  })));
});
